{"path": "/workspace/target/src/artifact_loader.py", "content": """"Case-record loading for the deployed candidate.

Release population authority is ``source_manifest.json`` (active entries only).
Canonical identity authority is the release registry joined on ``record_key``.
Landing display identifiers and unlisted landing files are never authority.
"""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any


def _read_jsonl(path: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    if not path.exists():
        return rows
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            rows.append(json.loads(line))
        except json.JSONDecodeError:
            continue
    return rows


def load_manifest(artifact_root: Path) -> dict[str, Any]:
    path = artifact_root / "source_manifest.json"
    if not path.exists():
        return {}
    return json.loads(path.read_text(encoding="utf-8"))


def load_registry(artifact_root: Path, manifest: dict[str, Any]) -> dict[str, dict[str, Any]]:
    name = str(manifest.get("identity_registry") or "release_registry.jsonl")
    registry: dict[str, dict[str, Any]] = {}
    for row in _read_jsonl(artifact_root / name):
        key = row.get("record_key")
        if key is None:
            continue
        registry[str(key)] = row
    return registry


def load_cases(artifact_root: Path) -> list[dict[str, Any]]:
    """Return the released case population with canonical identity attached."""
    artifact_root = Path(artifact_root)
    manifest = load_manifest(artifact_root)
    registry = load_registry(artifact_root, manifest)
    identity_key = str(manifest.get("identity_key") or "record_key")

    entries = [e for e in manifest.get("files", []) if e.get("active", True)]
    if not entries:  # defensive fallback only
        entries = [
            {"domain": p.name.split("_")[0].split("(")[0], "path": f"cases/{p.name}"}
            for p in sorted((artifact_root / "cases").glob("*.jsonl"))
        ]

    rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    for entry in entries:
        rel = str(entry.get("path", ""))
        path = artifact_root / rel
        fallback_domain = str(entry.get("domain") or path.name.split("_")[0].split("(")[0])
        for row in _read_jsonl(path):
            key = row.get(identity_key)
            if key is None:
                continue
            key = str(key)
            if registry:
                identity = registry.get(key)
                if identity is None:
                    # not part of the released population
                    continue
                canonical_pmcid = str(identity.get("pmcid", ""))
                domain = str(identity.get("domain") or fallback_domain)
            else:
                canonical_pmcid = str(row.get("pmcid", ""))
                domain = fallback_domain
            if key in seen:
                continue
            seen.add(key)
            record = dict(row)
            record["record_key"] = key
            record["pmcid"] = canonical_pmcid
            record["source"] = domain
            rows.append(record)
    return rows


def load_request(path: Path) -> dict[str, Any]:
    return json.loads(Path(path).read_text(encoding="utf-8"))
"}

{"path": "/workspace/target/src/text_views.py", "content": """"Text normalization and document assembly for the deployed candidate.

The serving boundary is pre-outcome: post-adjudication or display-only fields
(``final_diagnosis``, ``domain_hits``, ``journal``, identifiers) are not
eligible retrieval text. Only the pre-outcome narrative view is indexed.
"""
from __future__ import annotations

import re
import unicodedata
from typing import Any

ELIGIBLE_FIELDS = ("title", "case_summary")


def normalize(text: str) -> str:
    text = unicodedata.normalize("NFKC", str(text)).lower()
    return re.sub(r"\s+", " ", text).strip()


def document_text(row: dict[str, Any]) -> str:
